package com.onlinelibrary.dao.impl;
import com.onlinelibrary.dao.UserDAO; import com.onlinelibrary.model.User; import com.onlinelibrary.util.DBConnection; import java.sql.*; import java.util.*;
public class UserDAOImpl implements UserDAO {
 private User map(ResultSet r)throws SQLException{return new User(r.getLong("id"),r.getString("membership_id"),r.getString("name"),r.getString("email"),r.getString("password_hash"),r.getString("role"),r.getString("status"));}
 public Optional<User> findByEmail(String email)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public Optional<User> findById(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public List<User> findMembers(String term)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE role='MEMBER' AND (name LIKE ? OR email LIKE ? OR membership_id LIKE ?) ORDER BY name")){String q="%"+(term==null?"":term)+"%";p.setString(1,q);p.setString(2,q);p.setString(3,q);try(ResultSet r=p.executeQuery()){List<User>out=new ArrayList<>();while(r.next())out.add(map(r));return out;}}}
 public User createMember(User u)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(membership_id,name,email,password_hash,role,status) VALUES(?,?,?,?,'MEMBER','ACTIVE')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,u.getMembershipId());p.setString(2,u.getName());p.setString(3,u.getEmail());p.setString(4,u.getPasswordHash());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())u.setId(r.getLong(1));}try(PreparedStatement pref=c.prepareStatement("INSERT INTO notification_preferences(member_id) VALUES(?)")){pref.setLong(1,u.getId());pref.executeUpdate();}return u;}catch(SQLIntegrityConstraintViolationException e){throw new com.onlinelibrary.exception.DuplicateMembershipException("Membership ID or email already exists",e);}}
 public void updateMember(User u)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET membership_id=?,name=?,email=? WHERE id=? AND role='MEMBER'")){p.setString(1,u.getMembershipId());p.setString(2,u.getName());p.setString(3,u.getEmail());p.setLong(4,u.getId());p.executeUpdate();}catch(SQLIntegrityConstraintViolationException e){throw new com.onlinelibrary.exception.DuplicateMembershipException("Membership ID or email already exists",e);}}
 public void deactivate(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET status='INACTIVE' WHERE id=? AND role='MEMBER'")){p.setLong(1,id);p.executeUpdate();}}
 public void updateProfile(User u,boolean changePassword)throws SQLException{String q=changePassword?"UPDATE users SET name=?,email=?,password_hash=? WHERE id=?":"UPDATE users SET name=?,email=? WHERE id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,u.getName());p.setString(2,u.getEmail());if(changePassword){p.setString(3,u.getPasswordHash());p.setLong(4,u.getId());}else p.setLong(3,u.getId());p.executeUpdate();}catch(SQLIntegrityConstraintViolationException e){throw new com.onlinelibrary.exception.DuplicateMembershipException("Email already exists",e);}}
 public long countActiveMembers()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM users WHERE role='MEMBER' AND status='ACTIVE'" );ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}
}


